func (q *Queries) UpdateArmadilhaDados(ctx context.Context, arg UpdateArmadilhaDadosParams) (Armadilha, error) {
	row := q.db.QueryRow(ctx, updateArmadilhaDados,
		arg.InstaladaEm,
		arg.AgenteID,
		arg.Latitude,
		arg.Longitude,
		arg.Anotacao,
		arg.ID,
	)
	var i Armadilha
	err := row.Scan(
		&i.ID,
		&i.Tipo,
		&i.IDExterno,
		&i.LocalID,
		&i.InstaladaEm,
		&i.AgenteID,
		&i.Latitude,
		&i.Longitude,
		&i.Anotacao,
		&i.Status,
		&i.RetiradaEm,
		&i.RetiradoPorID,
		&i.CriadoPor,
		&i.CriadoEm,
		&i.AtualizadoEm,
		&i.DeletedAt,
		&i.DeletedBy,
	)
	return i, err
}

const updateArmadilhaRegistro = `-- name: UpdateArmadilhaRegistro :execrows
UPDATE armadilha_registros SET ovos = $1, nivel_agua = $2, anotacao = $3
WHERE id = $4 AND armadilha_id = $5 AND deleted_at IS NULL
`

type UpdateArmadilhaRegistroParams struct {
	Ovos        pgtype.Int4 `json:"ovos"`
	NivelAgua   string      `json:"nivel_agua"`
	Anotacao    string      `json:"anotacao"`
	ID          int64       `json:"id"`
	ArmadilhaID int64       `json:"armadilha_id"`
}

func (q *Queries) UpdateArmadilhaRegistro(ctx context.Context, arg UpdateArmadilhaRegistroParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateArmadilhaRegistro,
		arg.Ovos,
		arg.NivelAgua,
		arg.Anotacao,
		arg.ID,
		arg.ArmadilhaID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
